-- AUTOGENERATED XenQuest Bulk Guidance ALL QUESTS — LOCAL TEST ONLY.
-- Source: supplied QuestieDB Forever tables. Provisional candidates, NOT verified.
-- Game-client quest title + objective-label guards are mandatory.
-- Manual entries in Data/QuestGuidance.lua always win; no raw external DB bundled.
local ADDON_NAME, addon = ...
addon.QuestGuidanceData = addon.QuestGuidanceData or {formatVersion=1, questsByID={}, questsByTitle={}}
local data = addon.QuestGuidanceData
data.questsByID = data.questsByID or {}
local function add(id, title, objectives)
    local prior = data.questsByID[id]
    if prior then
        if prior.title and prior.title:lower() ~= title:lower() then return end
        prior.objectives = prior.objectives or {}
        for label, description in pairs(objectives) do
            if prior.objectives[label] == nil then prior.objectives[label] = description end
        end
    else
        data.questsByID[id] = {title=title, objectives=objectives, requireTitle=true}
    end
end
